fun countSetBits(n: Int): Int {
    var x = n
    var count = 0
    while (x != 0) {
        x = x and (x - 1)                  // removes the lowest set bit
        count++
    }
    return count
}
// Time: O(number of set bits)   Space: O(1)
// Built in: n.countOneBits()

fun singleNumber(nums: IntArray): Int {
    var result = 0
    for (x in nums) result = result xor x      // pairs cancel, the single number remains
    return result
}
// Time: O(n)   Space: O(1)

fun allSubsets(nums: IntArray): List<List<Int>> {
    val n = nums.size
    val result = mutableListOf<List<Int>>()
    for (mask in 0 until (1 shl n)) {          // each mask is one subset
        val subset = ArrayList<Int>()
        for (i in 0 until n) {
            if ((mask and (1 shl i)) != 0) subset.add(nums[i])    // bit i means 'take nums[i]'
        }
        result.add(subset)
    }
    return result
}
// Time: O(n * 2^n)   Space: O(n) beyond the output
// Practical for n up to about 20

fun forEachSubmask(mask: Int, action: (Int) -> Unit) {
    var sub = mask
    while (sub > 0) {
        action(sub)
        sub = (sub - 1) and mask               // next smaller submask
    }
    action(0)                                  // the empty submask
}
// Time: O(2^k) where k is the number of set bits in mask
// Summed over all masks this is O(3^n), used in subset-partition DP

fun singleNumberII(nums: IntArray): Int {
    var ones = 0                               // bits seen once (mod 3)
    var twos = 0                               // bits seen twice (mod 3)
    for (x in nums) {
        ones = (ones xor x) and twos.inv()
        twos = (twos xor x) and ones.inv()
    }
    return ones
}
// Time: O(n)   Space: O(1)
// Each bit position counts appearances modulo 3 using the two variables

fun singleNumberIII(nums: IntArray): IntArray {
    var xor = 0
    for (x in nums) xor = xor xor x            // xor = a xor b, the two unique numbers
    val diffBit = xor and -xor                 // a bit where a and b differ
    var a = 0
    var b = 0
    for (x in nums) {
        if ((x and diffBit) == 0) a = a xor x  // split the numbers into two groups by that bit
        else b = b xor x
    }
    return intArrayOf(a, b)
}
// Time: O(n)   Space: O(1)
// Each group contains exactly one unique number plus pairs that cancel

fun missingNumber(nums: IntArray): Int {
    var result = nums.size                     // start with n, since indices only go up to n - 1
    for (i in nums.indices) {
        result = result xor i xor nums[i]      // every present number cancels its index
    }
    return result
}
// Time: O(n)   Space: O(1)

fun hammingWeight(n: Int): Int = n.countOneBits()

fun hammingDistance(x: Int, y: Int): Int = (x xor y).countOneBits()   // differing positions

fun totalHammingDistance(nums: IntArray): Int {
    var total = 0
    for (bit in 0 until 32) {
        var ones = 0
        for (x in nums) ones += (x shr bit) and 1
        total += ones * (nums.size - ones)                         // each (one, zero) pair differs here
    }
    return total
}
// Total Hamming Distance: O(32 * n) instead of O(n²)

fun countBitsArray(n: Int): IntArray {
    val dp = IntArray(n + 1)
    for (i in 1..n) {
        dp[i] = dp[i shr 1] + (i and 1)        // bits of i = bits of i / 2, plus the last bit
    }
    return dp
}
// Time: O(n)   Space: O(n)

fun reverseBits(n: Int): Int {
    var x = n
    var result = 0
    repeat(32) {
        result = (result shl 1) or (x and 1)   // append the lowest bit of x to result
        x = x ushr 1                           // ushr so the sign bit does not smear
    }
    return result
}
// Time: O(32)   Space: O(1)

fun getSum(a: Int, b: Int): Int {
    var x = a
    var y = b
    while (y != 0) {
        val carry = (x and y) shl 1            // positions where both bits are 1 carry to the left
        x = x xor y                            // addition without the carry
        y = carry
    }
    return x
}
// Time: O(32)   Space: O(1)
// Works for negative numbers because of two's complement

fun rangeBitwiseAnd(left: Int, right: Int): Int {
    var l = left
    var r = right
    var shift = 0
    while (l != r) {                           // keep only the common binary prefix
        l = l shr 1
        r = r shr 1
        shift++
    }
    return l shl shift
}
// Time: O(32)   Space: O(1)

fun maxProduct(words: Array<String>): Int {
    val masks = IntArray(words.size)
    for ((i, w) in words.withIndex()) {
        for (c in w) masks[i] = masks[i] or (1 shl (c - 'a'))      // one bit per letter
    }
    var best = 0
    for (i in words.indices) {
        for (j in i + 1 until words.size) {
            if ((masks[i] and masks[j]) == 0) {                      // no shared letters
                best = maxOf(best, words[i].length * words[j].length)
            }
        }
    }
    return best
}
// Time: O(total letters + n²)   Space: O(n)

fun grayCode(n: Int): List<Int> = List(1 shl n) { it xor (it shr 1) }
// Consecutive values differ in exactly one bit
// Time: O(2^n)   Space: O(2^n)

fun validUtf8(data: IntArray): Boolean {
    var remaining = 0                                  // continuation bytes still expected
    for (item in data) {
        val b = item and 0xFF                          // only the lowest 8 bits matter
        if (remaining == 0) {
            remaining = when {
                (b shr 7) == 0b0 -> 0                  // 0xxxxxxx
                (b shr 5) == 0b110 -> 1                // 110xxxxx
                (b shr 4) == 0b1110 -> 2               // 1110xxxx
                (b shr 3) == 0b11110 -> 3              // 11110xxx
                else -> return false
            }
        } else {
            if ((b shr 6) != 0b10) return false        // continuation byte: 10xxxxxx
            remaining--
        }
    }
    return remaining == 0
}
// Time: O(n)   Space: O(1)

fun shortestPathLength(graph: Array<IntArray>): Int {
    val n = graph.size
    val full = (1 shl n) - 1                            // all nodes visited
    val visited = Array(n) { BooleanArray(1 shl n) }    // state = (current node, set of visited nodes)
    val queue = ArrayDeque<IntArray>()
    for (i in 0 until n) {                              // start from every node at once
        queue.addLast(intArrayOf(i, 1 shl i, 0))
        visited[i][1 shl i] = true
    }
    while (queue.isNotEmpty()) {
        val (node, mask, dist) = queue.removeFirst()
        if (mask == full) return dist
        for (next in graph[node]) {
            val newMask = mask or (1 shl next)
            if (!visited[next][newMask]) {
                visited[next][newMask] = true
                queue.addLast(intArrayOf(next, newMask, dist + 1))
            }
        }
    }
    return 0
}
// Time: O(2^n * n * degree)   Space: O(2^n * n)

fun tsp(dist: Array<IntArray>): Int {
    val n = dist.size
    if (n == 1) return 0
    val inf = Int.MAX_VALUE / 2
    // dp[mask][last] = cheapest way to visit the cities in mask, ending at last
    val dp = Array(1 shl n) { IntArray(n) { inf } }
    dp[1][0] = 0                                        // start at city 0, only city 0 visited

    for (mask in 1 until (1 shl n)) {
        for (last in 0 until n) {
            if ((mask and (1 shl last)) == 0 || dp[mask][last] >= inf) continue
            for (next in 0 until n) {
                if ((mask and (1 shl next)) != 0) continue            // already visited
                val newMask = mask or (1 shl next)
                dp[newMask][next] = minOf(dp[newMask][next], dp[mask][last] + dist[last][next])
            }
        }
    }

    var best = inf
    val full = (1 shl n) - 1
    for (last in 1 until n) {
        best = minOf(best, dp[full][last] + dist[last][0])             // return to the start
    }
    return best
}
// Time: O(2^n * n²)   Space: O(2^n * n)
// Practical for n up to about 20

fun subsetSumCount(nums: IntArray, target: Int): Int {
    val n = nums.size
    var count = 0
    for (mask in 0 until (1 shl n)) {
        var sum = 0
        for (i in 0 until n) {
            if ((mask and (1 shl i)) != 0) sum += nums[i]
        }
        if (sum == target) count++
    }
    return count
}
// Time: O(n * 2^n)   Fine for n <= 20; use DP when the target is small and n is large
